<?php declare(strict_types=1);
use Kulturhus\Verein\Finance;
require_once __DIR__.'/return-order-bank-proof.php';require_once __DIR__.'/sepa-native-contracts.php';require_once __DIR__.'/transfer-native-contracts.php';require_once __DIR__.'/transfer-native-recovery-fixture.php';

// Reuse genuine independently verified order preparation. Old fixture checks
// are prerequisites, not counted again as new returned-payment conditions.
(static function(PDO $db,callable $check,callable $deny,callable $whole,callable $key):void{
    $prior=getenv('VEREIN_MEMBER_BANK_KEY_PATH');$referenceChecks=0;$reference=static function(bool $ok,string $label)use(&$referenceChecks):void{if(!$ok)throw new RuntimeException('Actual reference bank fixture: '.$label);++$referenceChecks;};
    try{
        $sepa=ownSepaNativeContracts($db,$reference);$ledger=$sepa['finance'];$entry=$sepa['annual'];$raw=($sepa['inputFor'])($entry);$review=$sepa['native']->prepare($raw);$prepared=$sepa['native']->accept($raw,$key(),$review['hash'],true);$activeOrderId=$prepared['result']['order']['id'];$sepa['service']->approve($activeOrderId,1);$sepa['service']->export($activeOrderId,2);$activeOrder=$sepa['service']->get($activeOrderId);$check($activeOrder['items'][0]['state']==='active'&&$activeOrder['state']==='exported','genuine direct debit guard uses its actual active exported order and exact invoice');$current=$ledger->entry($entry);$ledger->recordPayment($entry,(int)$current['version'],$sepa['account'],$sepa['notice'],Finance::decimal((int)$current['amount_cents']));$original=$ledger->allocations($entry)[0]['transaction_id'];$counter=$ledger->createTransaction(['account'=>$sepa['account'],'direction'=>'expense','amount'=>Finance::decimal((int)$current['amount_cents']),'booked_on'=>$sepa['notice'],'description'=>'Own actual returned prepared direct debit payment'],$key());$before=$whole();$deny(fn()=>$ledger->paymentReturnReview($original,$counter,'Own active direct debit must keep its original return workflow'),'actual exported active direct debit blocks generic demand reopening');$check($whole()===$before,'refused generic payment return preserves the entire actual debit order mandate original XML invoice payment and counter');$raw=\Kulturhus\Verein\Finance\Banking\NativeSepa\SepaInput::initial($activeOrderId);$raw['operation']='return';$raw['data']=array_replace($raw['data'],['item'=>$activeOrder['items'][0]['id'],'transaction'=>$counter,'reason'=>'Own actual full debit return through its correct original workflow']);$review=$sepa['native']->prepare($raw);$returned=$sepa['native']->accept($raw,$key(),$review['hash'],true);$check($returned['result']['return']['entry']['payment_state']==='open'&&$ledger->transactionDetail($counter)['reversal_of']===$original&&$ledger->paymentReturnHistory($original)===[],'actual original direct debit return still reopens its own demand with precisely the existing movements and no generic first');

        $transfer=ownTransferNativeContracts($db,$reference,Closure::fromCallable('recoveryTransferPdf'));$ledger=$transfer['finance']??new Finance($db,$transfer['actor']);$orders=$transfer['service'];
        $early=$transfer['invoice']['entry'];$current=$ledger->entry($early);$ledger->recordPayment($early,(int)$current['version'],$transfer['account'],$transfer['today']);$earlySource=$ledger->allocations($early)[0]['transaction_id'];$earlyCounter=$ledger->createTransaction(['account'=>$transfer['account'],'direction'=>'income','amount'=>Finance::decimal((int)$current['amount_cents']),'booked_on'=>$transfer['today'],'description'=>'Own actual manual payment returned before scheduled bank execution'],$key());$before=$whole();$deny(fn()=>$ledger->paymentReturnReview($earlySource,$earlyCounter,'Own future submitted bank order is not resolved by earlier manual money'),'manual money booked before the submitted order execution cannot resolve that still-pending bank order');$check($whole()===$before,'future submission guard retains its whole old order original invoice earlier actual money and exact original allocation');
        foreach(['prepared','approved','exported']as$state){
