            $current=$ledger->entry($entry);$ledger->recordPayment($entry,(int)$current['version'],$transfer['account'],$transfer['today'],'100');$original=$ledger->allocations($entry)[0]['transaction_id'];$counter=$ledger->createTransaction(['account'=>$transfer['account'],'direction'=>'income','amount'=>'100','booked_on'=>$transfer['today'],'description'=>'Own actual '.$state.' bank payment returned'],$key());$before=$whole();$deny(fn()=>$ledger->paymentReturnReview($original,$counter,'Own '.$state.' bank order must be resolved first'),'actual '.$state.' transfer blocks generic returned-payment demand reopening');$check($whole()===$before,'refused '.$state.' payment return preserves every original whole order invoice approval money and allocation cell');
            if($state!=='exported'){$orders->cancel($order,$state==='prepared'?1:2);$review=$ledger->paymentReturnReview($original,$counter,'Own bank order explicitly cancelled; actual payment returned');$check($review['review']['source']['eligible'],'deliberate cancellation of the actual '.$state.' order permits a fresh returned-payment review');}else{$orders->submitted($order,3,'OWN-LOCAL-ACK-NO-REAL-BANK');$q=$db->prepare('SELECT * FROM finance_transfer_orders WHERE club_id=? AND id=?');$q->execute([$transfer['club'],$order]);$oldOrder=$q->fetch();$reason='Own previously submitted payment actually returned; original supplier invoice stays due';$review=$ledger->paymentReturnReview($original,$counter,$reason);$returnedFirst=$ledger->returnPayment($original,(int)$review['review']['source']['transaction']['version'],$counter,(int)$review['review']['returned']['version'],$reason,$key(),$review['hash'],true);$check(!$ledger->paymentReturnResolvesTransfer($order),'actual full payment return alone does not infer the old bank-order relation');$deny(fn()=>$transfer['native']->prepare(($transfer['inputFor'])($entry)),'unconfirmed returned bank-order relation blocks a fresh payment');ownConfirmReturnedBankOrder($db,$transfer['actor'],$transfer['account'],$original,$counter,$returnedFirst['id'],$order,'prior-native-return');$check($ledger->paymentReturnResolvesTransfer($order),'actual whole bank proofs and explicit officer relation resolve the immutable old submission');$raw=($transfer['inputFor'])($entry);$review=$transfer['native']->prepare($raw);$replacement=$transfer['native']->accept($raw,$key(),$review['hash'],true);$newOrder=$replacement['result']['order']['id'];$q->execute([$transfer['club'],$order]);$check($newOrder!==$order&&$q->fetch()===$oldOrder&&$replacement['result']['order']['total_cents']===10000,'a fresh independently reviewed supplier payment may follow the actual return while its old whole submitted order remains exact');$before=$whole();$deny(fn()=>$transfer['native']->prepare($raw),'new pending replacement still blocks a second concurrent payment of the reopened invoice');$check($whole()===$before,'refused duplicate replacement preserves every full original payment return and bank order cell');}
        }
        echo json_encode(['reference_bank_fixture_checks'=>$referenceChecks,'counted_as_new_return_conditions'=>false,'external_actions'=>0],JSON_THROW_ON_ERROR)."\n";
    }finally{putenv($prior===false?'VEREIN_MEMBER_BANK_KEY_PATH':'VEREIN_MEMBER_BANK_KEY_PATH='.$prior);}
})($db,$check,$deny,$whole,$key);
